{
  "implementation": "def solve(case):
    # Validate required top-level keys
    if 'threshold' not in case or 'calls' not in case:
        raise ValueError("case must contain 'threshold' and 'calls'")
    threshold = case['threshold']
    calls = case['calls']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    accepted_call_ids = []
    diagnostics = []

    for call in calls:
        # Validate required fields per call
        required = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
        for key in required:
            if key not in call:
                raise ValueError(f"Missing required field '{key}' in call")
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        pred_tokens = call['prediction_tokens']
        parseable = call['parseable']

        # Type checks
        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        if not isinstance(loss_without, (int, float)):
            raise ValueError("loss_without_call must be a number")
        if not isinstance(loss_with, (int, float)):
            raise ValueError("loss_with_call must be a number")
        if not isinstance(pred_tokens, int):
            raise ValueError("prediction_tokens must be an integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        # Handle zero prediction_tokens (should not occur per spec, but guard)
        if pred_tokens <= 0:
            raise ValueError("prediction_tokens must be positive")

        # Compute normalized gain
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens

        # Determine acceptance
        accepted = parseable and normalized_gain >= threshold

        if accepted:
            accepted_call_ids.append(call_id)

        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': normalized_gain
        })

    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }
